package com.fasterxml.jackson.databind.type;

import com.fasterxml.jackson.databind.JavaType;
import com.fasterxml.jackson.databind.type.BasicType;
import com.fasterxml.jackson.databind.type.TypeFactory;
import java.io.*;
import java.math.*;
import java.util.*;
import java.util.HashMap;
import java.util.Map;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;

/**
 * Unit tests for MapType.construct(Class, JavaType, JavaType)
 */
public class MapType_construct_TriageGen1Test {

    @Test
    public void testConstruct_Success() {
        // Arrange
        TypeFactory typeFactory = TypeFactory.defaultInstance();
        Class<?> rawType = HashMap.class;
        JavaType keyType = typeFactory.constructType(String.class);
        JavaType valueType = typeFactory.constructType(Integer.class);

        // Act
        // Note: The method is deprecated, but we are testing its current implementation logic
        MapType result = MapType.construct(rawType, keyType, valueType);

        // Assert
        assertNotNull("Result should not be null", result);
        assertEquals("Raw type should match", rawType, result.getRawClass());
        assertEquals("Key type should match", keyType, result.getKeyType());
        assertEquals("Value type should match", valueType, result.getValueType());

        // Verify toString to ensure internal state is consistent with the constructor call
        String toStringResult = result.toString();
        assert(toStringResult.contains("java.util.HashMap"));
        assert(toStringResult.contains("java.lang.String"));
        assert(toStringResult.contains("java.lang.Integer"));
    }

    @Test
    public void testConstruct_WithDifferentTypes() {
        // Arrange
        TypeFactory typeFactory = TypeFactory.defaultInstance();
        Class<?> rawType = Map.class;
        JavaType keyType = typeFactory.constructType(Long.class);
        JavaType valueType = typeFactory.constructType(Double.class);

        // Act
        MapType result = MapType.construct(rawType, keyType, valueType);

        // Assert
        assertNotNull(result);
        assertEquals(Map.class, result.getRawClass());
        assertEquals(keyType, result.getKeyType());
        assertEquals(valueType, result.getValueType());
    }

    @Test(expected = NullPointerException.class)
    public void testConstruct_NullRawType_ThrowsException() {
        // Arrange
        TypeFactory typeFactory = TypeFactory.defaultInstance();
        JavaType keyType = typeFactory.constructType(String.class);
        JavaType valueType = typeFactory.constructType(String.class);

        // Act
        // Passing null for rawType will likely cause a NullPointerException in _bogusSuperClass or MapType constructor
        MapType.construct(null, keyType, valueType);
    }

    @Test
    public void testConstruct_NullKeyOrValueType() {
        // Arrange
        TypeFactory typeFactory = TypeFactory.defaultInstance();
        Class<?> rawType = HashMap.class;
        JavaType keyType = null;
        JavaType valueType = typeFactory.constructType(String.class);

        // Act
        MapType result = MapType.construct(rawType, keyType, valueType);

        // Assert
        assertNotNull(result);
        assertEquals(rawType, result.getRawClass());
        assertEquals(null, result.getKeyType());
        assertEquals(valueType, result.getValueType());
    }
}
